<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class Inventory {
 public static function fail(string $m): never {throw ValidationException::withMessages(['operation'=>$m]);}
 public function state(){return DB::table('demo_state')->find(1)??abort(503,'Run database seeder first');}
 public function locked(callable $fn){return DB::transaction(function()use($fn){$s=DB::table('demo_state')->where('id',1)->lockForUpdate()->first();if(!$s)self::fail('Initialize demo first');return $fn($s);},3);}
 public function touch(bool $started=false): void {$q=DB::table('demo_state')->where('id',1);$q->increment('revision');if($started)$q->update(['started'=>true]);}
 public function product(int $id){return DB::table('products')->find($id)??abort(404);}
 public function available(int $id,string $date): float {return (float)DB::table('stock_lots')->where('product_id',$id)->where('expires_date','>=',$date)->sum('remaining');}
 private function move($p,$date,$kind,$qty,$key,$uid,$note=null): void {if(abs($qty)<.0000001)return;DB::table('stock_movements')->insert(['product_id'=>$p,'date'=>$date,'kind'=>$kind,'qty'=>round($qty,3),'event_key'=>$key,'user_id'=>$uid,'note'=>$note]);}
 private function addLot($p,$date,$qty,$key,$uid,$kind): void {DB::table('stock_lots')->insert(['product_id'=>$p->id,'received_date'=>$date,'expires_date'=>date('Y-m-d',strtotime($date.' +'.($p->shelf_life_days-1).' days')),'remaining'=>$qty,'source'=>'demo_pos']);$this->move($p->id,$date,$kind,$qty,$key,$uid);}
 private function consume($id,$date,$qty,$kind,$key,$uid): void {
  if($qty<=0)return;if($qty>$this->available($id,$date)+1e-7)self::fail('Stok layak pakai tidak cukup');$left=round($qty,3);
  foreach(DB::table('stock_lots')->where('product_id',$id)->where('expires_date','>=',$date)->where('remaining','>',0)->orderBy('expires_date')->orderBy('id')->lockForUpdate()->get() as $lot){$n=min($left,(float)$lot->remaining);DB::table('stock_lots')->where('id',$lot->id)->update(['remaining'=>round($lot->remaining-$n,3)]);$left=round($left-$n,3);if($left<=0)break;}
  if($left>0)self::fail('Ledger tidak konsisten');$this->move($id,$date,$kind,-$qty,$key,$uid);
 }
 public function sale(int $menu,int $requested,string $key,int $uid): array {return $this->locked(function($s)use($menu,$requested,$key,$uid){
  $old=DB::table('sales')->where('event_key',$key)->first();if($old){if($old->menu_id!=$menu||$old->requested!=$requested||$old->user_id!=$uid)self::fail('Idempotency conflict');return ['sold'=>$old->sold,'lost'=>$old->lost,'duplicate'=>true];}
  if($requested<1||$requested>10000)self::fail('Invalid requested quantity');if(!DB::table('menus')->where('id',$menu)->where('active',true)->exists())self::fail('Menu tidak aktif');$bom=DB::table('bom')->where('menu_id',$menu)->orderBy('product_id')->get();if($bom->isEmpty())self::fail('BOM kosong');$sold=$requested;
  foreach($bom as $b)$sold=min($sold,(int)floor(($this->available($b->product_id,$s->open_date)+1e-8)/(float)$b->qty));$lost=$requested-$sold;
  $id=DB::table('sales')->insertGetId(['menu_id'=>$menu,'date'=>$s->open_date,'requested'=>$requested,'sold'=>$sold,'lost'=>$lost,'event_key'=>$key,'source'=>'demo_pos','user_id'=>$uid]);
  foreach($bom as $b){$u=round($sold*$b->qty,3);$d=round($requested*$b->qty,3);$this->consume($b->product_id,$s->open_date,$u,'usage','sale-'.$id.'-'.$b->product_id,$uid);DB::table('sale_items')->insert(['sale_id'=>$id,'product_id'=>$b->product_id,'usage_qty'=>$u,'demand_qty'=>$d]);}$this->touch(true);return ['sold'=>$sold,'lost'=>$lost,'duplicate'=>false];
 });}
 public function waste(int $id,float $qty,string $key,int $uid):void {$this->locked(function($s)use($id,$qty,$key,$uid){$this->product($id);$old=DB::table('stock_movements')->where('event_key','waste-'.$key)->first();if($old){if($old->product_id!=$id||abs($old->qty+$qty)>1e-7||$old->user_id!=$uid)self::fail('Idempotency conflict');return;} $this->consume($id,$s->open_date,$qty,'waste','waste-'.$key,$uid);$this->touch(true);});}
 public function draft(int $pid,float $qty,string $expected,string $key,int $uid,?int $run=null,?string $policy=null):int {return $this->locked(function($s)use($pid,$qty,$expected,$key,$uid,$run,$policy){
  $old=DB::table('orders')->where('event_key',$key)->first();if($old){if($old->product_id!=$pid||abs($old->qty-$qty)>1e-7||$old->expected_date!=$expected||$old->created_by!=$uid||$old->forecast_run_id!=$run||$old->policy!=$policy)self::fail('Idempotency conflict');return $old->id;}
  $p=$this->product($pid);if($qty<=0||abs($qty/$p->order_multiple-round($qty/$p->order_multiple))>1e-7)self::fail('Jumlah harus kelipatan order');if($expected<$s->open_date)self::fail('Tanggal penerimaan tidak boleh sebelum hari terbuka');if(!$p->is_production&&$s->started&&$expected===$s->open_date)self::fail('Lead time satu hari: setelah aktivitas dimulai, pesan untuk hari berikutnya');
  if($run){$f=DB::table('forecast_runs')->find($run);if(!$f||$f->revision!=$s->revision||$f->as_of!=$s->closed_through||$s->started||$expected!==$f->target_date)self::fail('Rekomendasi sudah kedaluwarsa; generate ulang sebelum aktivitas stok');$rec=json_decode($f->recommendation_json,true);$match=collect($rec['recommendations'])->first(fn($r)=>$r['product_name']===$p->name&&$r['policy']===$policy);if(!$match||abs($qty-$match['recommended_qty'])>1e-7)self::fail('Jumlah tidak cocok dengan rekomendasi');if(DB::table('orders')->where('product_id',$pid)->where('expected_date',$expected)->where('status','draft')->exists())self::fail('Draft aktif untuk produk dan tanggal ini sudah ada; setujui atau batalkan dulu');}
  if($p->is_production&&DB::table('orders')->where('product_id',$pid)->where('expected_date',$expected)->whereIn('status',['draft','approved','partially_received'])->exists())self::fail('Rencana produksi aktif sudah ada');
  return DB::table('orders')->insertGetId(['product_id'=>$pid,'type'=>$p->is_production?'production':'purchase','status'=>'draft','qty'=>$qty,'received'=>0,'expected_date'=>$expected,'event_key'=>$key,'forecast_run_id'=>$run,'policy'=>$policy,'created_by'=>$uid,'created_at'=>now(),'updated_at'=>now()]);
 });}
 public function transition(int $id,string $action,int $uid):void {$this->locked(function($s)use($id,$action,$uid){$o=DB::table('orders')->find($id)??abort(404);if($action==='approve'){if($o->status!=='draft')self::fail('Hanya draft dapat disetujui');if($o->expected_date<$s->open_date)self::fail('Tanggal rencana sudah lewat');if($o->forecast_run_id){$f=DB::table('forecast_runs')->find($o->forecast_run_id);if(!$f||$f->as_of!==$s->closed_through||$s->started)self::fail('Draft rekomendasi lama atau hari telah dimulai; batalkan dan buat baru');}$data=['status'=>'approved','approved_by'=>$uid];}else{if(!in_array($o->status,['draft','approved','partially_received'],true))self::fail('Pesanan tidak dapat dibatalkan');$data=['status'=>'cancelled'];}DB::table('orders')->where('id',$id)->update($data+['updated_at'=>now()]);$this->touch();});}
 public function receipt(int $id,float $qty,string $key,int $uid):void {$this->locked(function($s)use($id,$qty,$key,$uid){$old=DB::table('receipts')->where('event_key',$key)->first();if($old){if($old->order_id!=$id||abs($old->qty-$qty)>1e-7||$old->user_id!=$uid)self::fail('Idempotency conflict');return;}$o=DB::table('orders')->find($id)??abort(404);if(!in_array($o->status,['approved','partially_received'],true)||$qty<=0||$qty>$o->qty-$o->received+1e-7)self::fail('Penerimaan tidak valid');if($o->type==='production'&&($s->open_date!==$o->expected_date||abs($qty-round($qty))>1e-7))self::fail('Produksi nasi harus pada tanggal rencana dan porsi utuh');$p=$this->product($o->product_id);$rid=DB::table('receipts')->insertGetId(['order_id'=>$id,'date'=>$s->open_date,'qty'=>$qty,'event_key'=>$key,'user_id'=>$uid]);$this->addLot($p,$s->open_date,$qty,'receipt-'.$rid,$uid,$o->type==='production'?'production_receipt':'receipt');$total=round($o->received+$qty,3);DB::table('orders')->where('id',$id)->update(['received'=>$total,'status'=>abs($total-$o->qty)<1e-7?'received':'partially_received','updated_at'=>now()]);$this->touch(true);});}
 public function calendar(array $flags):void {$this->locked(function($s)use($flags){if($s->started)self::fail('Kalender hanya dapat diatur sebelum transaksi hari berjalan');DB::table('calendar_days')->where('date',$s->open_date)->update($flags+['source'=>'demo_scenario']);$this->touch();});}
 public function close(string $date,int $uid,bool $confirmed):void {$this->locked(function($s)use($date,$uid,$confirmed){if(!$confirmed||$date!==$s->open_date)self::fail('Konfirmasi penutupan hari diperlukan');
  foreach(DB::table('stock_lots')->where('expires_date','<=',$date)->where('remaining','>',0)->lockForUpdate()->get() as $lot){$this->move($lot->product_id,$date,'expiry',-(float)$lot->remaining,'expiry-'.$lot->id.'-'.$date,$uid,'Demo shelf life');DB::table('stock_lots')->where('id',$lot->id)->update(['remaining'=>0]);}
  foreach(DB::table('products')->get() as $p){$prev=DB::table('daily_history')->where('product_id',$p->id)->where('date',$s->closed_through)->first();if(!$prev)self::fail('Missing prior daily history');$sum=DB::table('sale_items')->join('sales','sales.id','=','sale_items.sale_id')->where('sales.date',$date)->where('sale_items.product_id',$p->id)->selectRaw('COALESCE(SUM(usage_qty),0) AS usage_qty, COALESCE(SUM(demand_qty),0) AS demand_qty')->first();$mov=DB::table('stock_movements')->where('product_id',$p->id)->where('date',$date);$incoming=(float)(clone $mov)->whereIn('kind',['receipt','production_receipt'])->sum('qty');$waste=-(float)(clone $mov)->whereIn('kind',['waste','expiry'])->sum('qty');$usage=(float)$sum->usage_qty;$closing=(float)DB::table('stock_lots')->where('product_id',$p->id)->sum('remaining');if(abs($prev->closing_stock+$incoming-$usage-$waste-$closing)>.0011)self::fail('Stock balance mismatch: '.$p->name);DB::table('daily_history')->insert(['product_id'=>$p->id,'date'=>$date,'quantity'=>$usage,'demand_quantity'=>$sum->demand_qty,'opening_stock'=>$prev->closing_stock,'incoming_stock'=>$incoming,'waste_quantity'=>$waste,'closing_stock'=>$closing,'source'=>'demo_pos']);}
  $next=date('Y-m-d',strtotime($date.' +1 day'));DB::table('calendar_days')->insert(['date'=>$next,'is_holiday'=>0,'is_promotion'=>0,'is_ramadan'=>0,'is_eid_period'=>0,'source'=>'demo_scenario']);DB::table('demo_state')->where('id',1)->update(['closed_through'=>$date,'open_date'=>$next,'started'=>false,'revision'=>$s->revision+1]);
 });}
}
